/** Emit a package.json next to the bundle so Node picks the right module type without warnings. */
function moduleType(type) {
  return {
    name: 'module-type',
    generateBundle() {
      this.emitFile({
        type: 'asset',
        fileName: 'package.json',
        source: JSON.stringify({ type }, null, 2),
      });
    },
  };
}

